{
  "decision": "needs_more_evidence",
  "objections": [
    {
      "severity": "minor",
      "problem": "The claim states 'always stretch your body after waking up' but the study only included stretching as part of a 1-hour brisk-walking session (6 days/week for 12 weeks), not as a standalone post-waking routine.",
      "requested_action": "Clarify if stretching is isolated or part of a combined exercise"
    },
    {
      "severity": "minor",
      "problem": "The study measured outcomes after 12 weeks, not immediate effects as claimed.",
      "requested_action": "Specify timing of effects for immediate vs. long-term"
    },
    {
      "severity": "minor",
      "problem": "The claim implies universal applicability, but the study only included elderly with PP ≥60 mmHg, not the general population.",
      "requested_action": "Limit to high-risk elderly groups"
    }
  ],
  "remaining_gaps": [
    "No data on immediate post-waking stretching effects"
  ]
}
